const item = $input.first().json;
const body = item.body || item;
const phoneNumberId = body.phoneNumberId || $env.META_PHONE_NUMBER_ID || '';
const accessToken = body.accessToken || $env.META_ACCESS_TOKEN || '';

if (body.mode === 'ping' || body.type === 'n8n_meta_test') {
  if (phoneNumberId && accessToken) {
    try {
      const res = await fetch(`https://graph.facebook.com/v21.0/${encodeURIComponent(phoneNumberId)}?fields=id,display_phone_number,verified_name`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      const data = await res.json().catch(() => ({}));
      return [{
        json: {
          ok: true,
          messageId: 'ping-ok',
          statusCode: 200,
          metaOk: res.ok,
          displayPhoneNumber: data.display_phone_number || null,
          verifiedName: data.verified_name || null,
          metaError: res.ok ? null : (data.error?.message || `HTTP ${res.status}`)
        }
      }];
    } catch (err) {
      return [{
        json: {
          ok: true,
          messageId: 'ping-ok',
          statusCode: 200,
          metaOk: false,
          metaError: err.message || 'Meta Graph API erişim hatası'
        }
      }];
    }
  }
  return [{
    json: {
      ok: true,
      messageId: 'ping-ok',
      statusCode: 200,
      status: 'n8n-ready'
    }
  }];
}

if (!phoneNumberId || !accessToken) {
  return [{
    json: {
      ok: false,
      statusCode: 400,
      error: 'Meta Phone Number ID veya Meta Access Token eksik.'
    }
  }];
}

let graphPayload;
if (body.mode === 'template' && body.template) {
  graphPayload = {
    messaging_product: 'whatsapp',
    to: body.to,
    type: 'template',
    template: {
      name: body.template.name,
      language: { code: body.template.language || 'tr' },
      components: body.template.components || []
    }
  };
} else if (body.mode === 'location' && body.location) {
  graphPayload = {
    messaging_product: 'whatsapp',
    to: body.to,
    type: 'location',
    location: body.location
  };
} else {
  graphPayload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: body.to,
    type: 'text',
    text: { preview_url: false, body: body.text || '' }
  };
}

try {
  const res = await fetch(`https://graph.facebook.com/v21.0/${encodeURIComponent(phoneNumberId)}/messages`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(graphPayload)
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    return [{
      json: {
        ok: false,
        statusCode: res.status,
        error: data?.error?.message || `Meta Graph API hatası (${res.status})`
      }
    }];
  }
  return [{
    json: {
      ok: true,
      statusCode: 200,
      messageId: data?.messages?.[0]?.id || data?.messageId || 'sent'
    }
  }];
} catch (err) {
  return [{
    json: {
      ok: false,
      statusCode: 502,
      error: err.message || 'Meta Graph API bağlantısı başarısız.'
    }
  }];
}
